// Generated by scripts/sync-valuation.py from shared/valuation/settlement.js as rp-valuation-settlement.js; edit the shared source.
// Empire-shared settlement-point valuation. Pure ES module.
//
// Contract for the count penalty:
// - cap is the settlement-point cap.
// - penaltyByCount (or the simpler happinessPenaltyPerExcessPoint) describes a
//   NON-NEGATIVE unhappiness penalty that is zero for every count <= cap.
// - town.happiness is the town's current net happiness, which already includes
//   the penalty at the current count.
// - hypothetical happiness at N' is:
//       h(N') = town.happiness + P(N) - P(N')
//   so each town uses its own current happiness instead of one shared value.
// - N->N-1 relief is zero unless N > cap; N->N+1 cost is zero unless N+1 > cap
//   (in particular it can be positive when N == cap).
//
// For a town, production in affected yields is converted to gold at the
// snapshot rate and scored with the gold weight, never the hammer weight. A
// town and a city are both included. A snapshot stores per-town per-turn and
// remaining (discounted) contributions; losing a town removes that town from
// surviving-town relief. snapshotWithoutTown is intentionally absent: removing
// a town changes N and is not just a contribution subtraction.

import {isFiniteNumber, normalizeWeights} from './rp-valuation-weights.js';
import {normalizeHorizon, discountedRangeSum} from './rp-valuation-horizon.js';
import {normalizePenaltyConfig, happinessPenalty} from './rp-valuation-happiness.js';

function penaltyTableAt(table, count) {
  if (Array.isArray(table)) return table[count];
  if (table && typeof table === 'object') {
    if (table[count] !== undefined) return table[count];
    if (table[String(count)] !== undefined) return table[String(count)];
  }
  return undefined;
}

function makePenaltyProvider({penaltyByCount, happinessPenaltyPerExcessPoint, cap, town}) {
  const townTable = town.penaltyByCount;
  const townRate = town.happinessPenaltyPerExcessPoint;
  if (townTable !== undefined) return validateTable(townTable, cap);
  if (townRate !== undefined) return validateRate(townRate, cap);
  if (happinessPenaltyPerExcessPoint !== undefined) return validateRate(happinessPenaltyPerExcessPoint, cap);
  if (penaltyByCount !== undefined) return validateTable(penaltyByCount, cap);
  return {status: 'not-estimated', reason: 'penalty-curve-required', missing: ['penaltyByCount or happinessPenaltyPerExcessPoint']};
}

function validateRate(rate, cap) {
  if (!isFiniteNumber(rate) || rate < 0) {
    return {status: 'invalid', reason: 'happinessPenaltyPerExcessPoint-non-negative-finite'};
  }
  return {
    status: 'estimated',
    kind: 'per-excess-point',
    rate,
    at(count) {
      return rate * Math.max(0, count - cap);
    }
  };
}

function validateTable(table, cap) {
  if (!Array.isArray(table) && (typeof table !== 'object' || table === null)) {
    return {status: 'invalid', reason: 'penaltyByCount-array-or-object'};
  }
  const entries = Array.isArray(table)
    ? Array.from(table.entries())
    : Object.entries(table).map(([key, value]) => [Number(key), value]);
  for (const [count, value] of entries) {
    if (!Number.isInteger(count) || count < 0) return {status: 'invalid', reason: 'penaltyByCount-index-non-negative-integer'};
    if (!isFiniteNumber(value) || value < 0) return {status: 'invalid', reason: `penaltyByCount-non-negative-finite:${count}`};
    if (count <= cap && value !== 0) {
      return {status: 'invalid', reason: `penaltyByCount-must-be-zero-at-or-below-cap:${count}`};
    }
  }
  return {
    status: 'estimated',
    kind: 'table',
    at(count) {
      if (count <= cap) return 0;
      const value = penaltyTableAt(table, count);
      if (!isFiniteNumber(value) || value < 0) return null;
      return value;
    }
  };
}

function townIsTown(town) {
  return town.kind === 'town' || town.isTown === true;
}

function valueForHappiness(town, currentCount, targetCount, provider, penaltyConfig, weights, goldPerProduction) {
  if (!Array.isArray(town.affectedYields)) {
    return {status: 'not-estimated', reason: `affectedYields-required:${town.id}`, perTurn: null, missing: [`town.${town.id}.affectedYields`]};
  }
  const affected = town.affectedYields;
  if (new Set(affected).size !== affected.length) {
    return {status: 'invalid', reason: `duplicate-affected-yield:${town.id}`, perTurn: null};
  }
  const currentPenalty = provider.at(currentCount);
  const targetPenalty = provider.at(targetCount);
  if (currentPenalty === null) return {status: 'not-estimated', reason: `penaltyByCount-missing:${currentCount}`, perTurn: null, missing: [`penaltyByCount.${currentCount}`]};
  if (targetPenalty === null) return {status: 'not-estimated', reason: `penaltyByCount-missing:${targetCount}`, perTurn: null, missing: [`penaltyByCount.${targetCount}`]};
  const happiness = town.happiness + currentPenalty - targetPenalty;
  const penalty = happinessPenalty(happiness, penaltyConfig);
  if (penalty === null) return {status: 'not-estimated', reason: `happiness-penalty-config-required:${town.id}`, perTurn: null, missing: [`penalty:${town.id}`]};
  const contributions = {};
  const effectiveYields = {};
  let perTurn = 0;
  const isTown = townIsTown(town);
  for (const key of affected) {
    if (key === 'happiness') return {status: 'invalid', reason: `happiness-is-not-a-penalized-yield:${town.id}`, perTurn: null};
    const weight = weights[key];
    if (!isFiniteNumber(weight)) return {status: 'invalid', reason: `unknown-or-invalid-yield:${key}`, perTurn: null};
    if (!town.baseYields || !isFiniteNumber(town.baseYields[key])) {
      return {status: 'not-estimated', reason: `town-base-yield-required:${town.id}.${key}`, perTurn: null, missing: [`town.${town.id}.baseYields.${key}`]};
    }
    const effective = town.baseYields[key] * Math.max(0, 1 - penalty);
    if (!isFiniteNumber(effective)) return {status: 'invalid', reason: `effective-yield-overflow:${town.id}.${key}`, perTurn: null};
    effectiveYields[key] = effective;
    if (key === 'production' && isTown) {
      if (town.productionGoldAlreadyInGold === true) {
        contributions[key] = 0;
        continue;
      }
      const rate = town.goldPerProduction ?? goldPerProduction;
      if (!isFiniteNumber(rate) || rate < 0) {
        return {status: 'not-estimated', reason: `town-gold-per-production-required:${town.id}`, perTurn: null, missing: [`goldPerProduction:${town.id}`]};
      }
      const contribution = effective * rate * weights.gold;
      if (!isFiniteNumber(contribution)) return {status: 'invalid', reason: `town-production-overflow:${town.id}`, perTurn: null};
      contributions[key] = contribution;
      perTurn += contribution;
    } else {
      const contribution = effective * weight;
      if (!isFiniteNumber(contribution)) return {status: 'invalid', reason: `contribution-overflow:${town.id}.${key}`, perTurn: null};
      contributions[key] = contribution;
      perTurn += contribution;
    }
  }
  if (!isFiniteNumber(perTurn)) return {status: 'invalid', reason: `town-value-overflow:${town.id}`, perTurn: null};
  return {
    status: 'estimated',
    perTurn,
    contributions,
    effectiveYields,
    happiness,
    currentPenalty,
    targetPenalty
  };
}

function extensionValue(callback, args) {
  if (callback === undefined) return {status: 'missing', perTurn: 0, remaining: 0, missing: []};
  if (typeof callback !== 'function') return {status: 'invalid', reason: 'stateValuation-function-required'};
  let value;
  try {
    value = callback(args);
  } catch (error) {
    return {status: 'invalid', reason: `stateValuation-threw:${error.message}`};
  }
  if (value === undefined || value === null) return {status: 'missing', perTurn: 0, remaining: 0, missing: ['state-valuation']};
  if (isFiniteNumber(value)) return {status: 'estimated', perTurn: value, remaining: null, oneTime: false, missing: []};
  if (typeof value === 'object') {
    const missing = Array.isArray(value.missing) ? [...value.missing] : [];
    const hasPerTurn = value.perTurn !== undefined || value.perTurnValue !== undefined;
    const hasRemaining = value.remaining !== undefined || value.remainingValue !== undefined;
    const perTurn = value.perTurn ?? value.perTurnValue;
    const remaining = value.remaining ?? value.remainingValue;
    if (!hasPerTurn && !hasRemaining) return {status: 'invalid', reason: 'stateValuation-needs-perTurn-or-remaining'};
    if (hasPerTurn && !isFiniteNumber(perTurn)) return {status: 'invalid', reason: 'stateValuation-perTurn-finite'};
    if (hasRemaining && !isFiniteNumber(remaining)) return {status: 'invalid', reason: 'stateValuation-remaining-finite'};
    return {
      status: missing.length ? 'partial' : 'estimated',
      perTurn: hasPerTurn ? perTurn : 0,
      remaining: hasRemaining ? remaining : null,
      oneTime: !hasPerTurn && hasRemaining,
      missing
    };
  }
  return {status: 'invalid', reason: 'stateValuation-number-or-object-required'};
}

function remainingFor(extension, horizon) {
  if (extension.remaining !== null) return extension.remaining;
  return discountedRangeSum(extension.perTurn, horizon);
}

// A correction is only the extra empire relief gained when one candidate town
// is removed. It is not the town's whole loss. A number is a per-turn gain;
// an object may supply a direct remaining value for one-time effects.
function normalizeLossRelief(value, horizon) {
  if (value === undefined) return {status: 'missing'};
  if (isFiniteNumber(value)) {
    const remaining = horizon.count === 0 ? 0 : discountedRangeSum(value, horizon);
    if (remaining === null) return {status: 'invalid', reason: 'loss-relief-discount-failed'};
    return {status: 'estimated', perTurn: value, remaining, source: 'number-per-turn'};
  }
  if (value && typeof value === 'object') {
    const hasPerTurn = value.perTurn !== undefined || value.perTurnValue !== undefined;
    const hasRemaining = value.remaining !== undefined || value.remainingValue !== undefined;
    const perTurn = value.perTurn ?? value.perTurnValue;
    const remaining = value.remaining ?? value.remainingValue;
    if (!hasPerTurn && !hasRemaining) return {status: 'invalid', reason: 'loss-relief-needs-perTurn-or-remaining'};
    if (hasPerTurn && !isFiniteNumber(perTurn)) return {status: 'invalid', reason: 'loss-relief-perTurn-finite'};
    if (hasRemaining && !isFiniteNumber(remaining)) return {status: 'invalid', reason: 'loss-relief-remaining-finite'};
    const resolved = hasRemaining ? remaining : (horizon.count === 0 ? 0 : discountedRangeSum(perTurn, horizon));
    if (resolved === null) return {status: 'invalid', reason: 'loss-relief-discount-failed'};
    return {status: 'estimated', perTurn: hasPerTurn ? perTurn : 0, remaining: resolved, source: 'object'};
  }
  return {status: 'invalid', reason: 'loss-relief-number-or-object-required'};
}

function lossReliefForTown({town, byId, callback, empireRelief, empireReliefRemaining, horizon, discountRate, count}) {
  let raw;
  if (byId && (byId[town.id] !== undefined || byId[String(town.id)] !== undefined)) {
    raw = byId[town.id] !== undefined ? byId[town.id] : byId[String(town.id)];
  } else if (typeof callback === 'function') {
    try {
      raw = callback({removedTownId: town.id, count, otherCount: count - 1, horizon, discountRate, scope: 'empire-loss'});
    } catch (error) {
      return {status: 'invalid', reason: `removedTownEmpireRelief-threw:${error.message}`};
    }
  }
  if (raw !== undefined) {
    const normalized = normalizeLossRelief(raw, horizon);
    return normalized.status === 'estimated'
      ? {...normalized, kind: 'empire-relief-gain-only'}
      : normalized;
  }
  if (empireRelief.perTurn === 0 && empireReliefRemaining === 0) {
    return {status: 'estimated', perTurn: 0, remaining: 0, source: 'empire-relief-zero', kind: 'empire-relief-gain-only'};
  }
  return {status: 'missing', missing: [`empire-relief-after-loss:${town.id}`], kind: 'empire-relief-gain-only'};
}

export function evaluateSettlementPointCounts({
  count,
  cap,
  towns = [],
  penaltyByCount,
  happinessPenaltyPerExcessPoint,
  goldPerProduction,
  penalty,
  weights = normalizeWeights(),
  currentTurn,
  endTurn,
  firstReceiptTurn,
  discountRate = 0,
  stateValuation,
  empireStateValuation,
  removedTownEmpireReliefById,
  removedTownEmpireRelief,
  playerId = null,
  saveId = null
} = {}) {
  if (!Number.isInteger(count) || count < 0) return Object.freeze({status: 'invalid', reason: 'count-non-negative-integer', snapshot: null});
  if (!Number.isInteger(cap) || cap < 0) return Object.freeze({status: 'invalid', reason: 'cap-non-negative-integer', snapshot: null});
  if (!Array.isArray(towns) || !towns.length) return Object.freeze({status: 'invalid', reason: 'towns-array-required', snapshot: null});
  const normalizedWeights = weights && weights.weights ? weights : normalizeWeights(weights);
  if (normalizedWeights.status === 'invalid') return Object.freeze({status: 'invalid', reason: 'invalid-weights', snapshot: null, invalid: normalizedWeights.invalid});
  const penaltyConfig = normalizePenaltyConfig(penalty);
  if (penaltyConfig.status === 'not-estimated') {
    return Object.freeze({status: 'not-estimated', reason: 'penalty-config-required', snapshot: null, missing: ['penalty']});
  }
  if (penaltyConfig.status === 'invalid') return Object.freeze({status: 'invalid', reason: penaltyConfig.reason, snapshot: null});
  const horizon = normalizeHorizon({currentTurn, endTurn, firstReceiptTurn, discountRate});
  if (horizon.status === 'invalid') return Object.freeze({status: 'invalid', reason: horizon.reason, snapshot: null});

  const missing = [];
  const perTown = [];
  let reliefPerTurn = 0;
  let costPerTurn = 0;
  let reliefRemaining = 0;
  let costRemaining = 0;
  const addMissing = (items) => {
    for (const item of items || []) if (!missing.includes(item)) missing.push(item);
  };
  if (stateValuation === undefined) addMissing(['risk']);
  if (empireStateValuation === undefined) addMissing(['celebration']);
  const seenTownIds = new Set();
  for (const town of towns) {
    if (!town || town.id === undefined) return Object.freeze({status: 'invalid', reason: 'town-id-required', snapshot: null});
    if (seenTownIds.has(String(town.id))) return Object.freeze({status: 'invalid', reason: `duplicate-town-id:${town.id}`, snapshot: null});
    seenTownIds.add(String(town.id));
  }

  for (const town of towns) {
    if (!isFiniteNumber(town.happiness)) {
      return Object.freeze({status: 'not-estimated', reason: `town-happiness-required:${town.id}`, snapshot: null, missing: Object.freeze([`town.${town.id}.happiness`])});
    }
    const provider = makePenaltyProvider({penaltyByCount, happinessPenaltyPerExcessPoint, cap, town});
    if (provider.status !== 'estimated') {
      return Object.freeze({status: provider.status, reason: provider.reason, snapshot: null, missing: Object.freeze(provider.missing || [])});
    }
    const current = valueForHappiness(town, count, count, provider, penaltyConfig, normalizedWeights.weights, goldPerProduction);
    if (current.status !== 'estimated') {
      return Object.freeze({status: current.status, reason: current.reason, snapshot: null, missing: Object.freeze(current.missing || [])});
    }
    let previous = null;
    if (count > 0) {
      previous = valueForHappiness(town, count, count - 1, provider, penaltyConfig, normalizedWeights.weights, goldPerProduction);
      if (previous.status !== 'estimated') return Object.freeze({status: previous.status, reason: previous.reason, snapshot: null, missing: Object.freeze(previous.missing || [])});
    }
    const next = valueForHappiness(town, count, count + 1, provider, penaltyConfig, normalizedWeights.weights, goldPerProduction);
    if (next.status !== 'estimated') return Object.freeze({status: next.status, reason: next.reason, snapshot: null, missing: Object.freeze(next.missing || [])});

    const reliefTown = previous ? Math.max(0, previous.perTurn - current.perTurn) : 0;
    const costTown = Math.max(0, current.perTurn - next.perTurn);

    const reliefExtension = extensionValue(stateValuation, {
      town, direction: 'relief', count, otherCount: count - 1, horizon, discountRate, scope: 'town'
    });
    if (reliefExtension.status === 'invalid') return Object.freeze({status: 'invalid', reason: reliefExtension.reason, snapshot: null});
    const costExtension = extensionValue(stateValuation, {
      town, direction: 'cost', count, otherCount: count + 1, horizon, discountRate, scope: 'town'
    });
    if (costExtension.status === 'invalid') return Object.freeze({status: 'invalid', reason: costExtension.reason, snapshot: null});
    addMissing(reliefExtension.missing);
    addMissing(costExtension.missing);

    const reliefTownRemaining = remainingFor(reliefExtension, horizon);
    const costTownRemaining = remainingFor(costExtension, horizon);
    if (reliefTownRemaining === null || costTownRemaining === null) return Object.freeze({status: 'invalid', reason: 'discount-failed', snapshot: null});

    const townReliefPerTurn = reliefTown + reliefExtension.perTurn;
    const townCostPerTurn = costTown + costExtension.perTurn;
    const baseReliefRemaining = horizon.count === 0 ? 0 : discountedRangeSum(reliefTown, horizon);
    const baseCostRemaining = horizon.count === 0 ? 0 : discountedRangeSum(costTown, horizon);
    if (baseReliefRemaining === null || baseCostRemaining === null) return Object.freeze({status: 'invalid', reason: 'discount-failed', snapshot: null});
    const townReliefRemaining = baseReliefRemaining + reliefTownRemaining;
    const townCostRemaining = baseCostRemaining + costTownRemaining;
    reliefPerTurn += townReliefPerTurn;
    costPerTurn += townCostPerTurn;
    reliefRemaining += townReliefRemaining;
    costRemaining += townCostRemaining;
    perTown.push(Object.freeze({
      id: town.id,
      kind: townIsTown(town) ? 'town' : 'city',
      happiness: Object.freeze({
        current: town.happiness,
        atPrevious: previous ? previous.happiness : null,
        atCurrent: current.happiness,
        atNext: next.happiness
      }),
      penalty: Object.freeze({
        atPrevious: previous ? previous.targetPenalty : null,
        atCurrent: current.currentPenalty,
        atNext: next.targetPenalty
      }),
      perTurn: Object.freeze({relief: townReliefPerTurn, cost: townCostPerTurn}),
      remaining: Object.freeze({relief: townReliefRemaining, cost: townCostRemaining}),
      contributions: Object.freeze({current: current.contributions, previous: previous?.contributions ?? null, next: next.contributions}),
      extensions: Object.freeze({
        relief: Object.freeze({perTurn: reliefExtension.perTurn, remaining: reliefTownRemaining, oneTime: reliefExtension.oneTime}),
        cost: Object.freeze({perTurn: costExtension.perTurn, remaining: costTownRemaining, oneTime: costExtension.oneTime})
      })
    }));
  }

  const empireRelief = extensionValue(empireStateValuation, {
    direction: 'relief', count, otherCount: count - 1, horizon, discountRate, scope: 'empire'
  });
  if (empireRelief.status === 'invalid') return Object.freeze({status: 'invalid', reason: empireRelief.reason, snapshot: null});
  const empireCost = extensionValue(empireStateValuation, {
    direction: 'cost', count, otherCount: count + 1, horizon, discountRate, scope: 'empire'
  });
  if (empireCost.status === 'invalid') return Object.freeze({status: 'invalid', reason: empireCost.reason, snapshot: null});
  addMissing(empireRelief.missing);
  addMissing(empireCost.missing);
  const empireReliefRemaining = remainingFor(empireRelief, horizon);
  const empireCostRemaining = remainingFor(empireCost, horizon);
  if (empireReliefRemaining === null || empireCostRemaining === null) return Object.freeze({status: 'invalid', reason: 'discount-failed', snapshot: null});
  reliefPerTurn += empireRelief.perTurn;
  costPerTurn += empireCost.perTurn;
  reliefRemaining += empireReliefRemaining;
  costRemaining += empireCostRemaining;
  if (![reliefPerTurn, costPerTurn, reliefRemaining, costRemaining].every(isFiniteNumber)) {
    return Object.freeze({status: 'invalid', reason: 'settlement-total-overflow', snapshot: null});
  }
  const lossReliefByTown = {};
  const lossReliefMissing = [];
  for (const town of towns) {
    const correction = lossReliefForTown({
      town, byId: removedTownEmpireReliefById, callback: removedTownEmpireRelief,
      empireRelief, empireReliefRemaining, horizon, discountRate, count
    });
    if (correction.status === 'invalid') return Object.freeze({status: 'invalid', reason: correction.reason, snapshot: null});
    if (correction.status === 'missing') {
      lossReliefMissing.push(...(correction.missing || []));
      continue;
    }
    lossReliefByTown[String(town.id)] = Object.freeze({
      perTurn: correction.perTurn,
      remaining: correction.remaining,
      source: correction.source,
      kind: correction.kind
    });
  }
  const lossReliefComplete = lossReliefMissing.length === 0;

  const snapshot = Object.freeze({
    status: missing.length ? 'partial' : 'estimated',
    complete: missing.length === 0,
    count,
    cap,
    atCap: count >= cap,
    overCap: count > cap,
    playerId,
    saveId,
    perTurn: Object.freeze({relief: reliefPerTurn, cost: costPerTurn}),
    remaining: Object.freeze({relief: reliefRemaining, cost: costRemaining}),
    perTown: Object.freeze(perTown),
    horizon,
    discountRate,
    missing: Object.freeze(missing),
    extensionsProvided: Object.freeze({town: stateValuation !== undefined, empire: empireStateValuation !== undefined}),
    lossRelief: Object.freeze({
      complete: lossReliefComplete,
      byTown: Object.freeze(lossReliefByTown),
      missing: Object.freeze(lossReliefMissing),
      kind: 'empire-relief-gain-only'
    }),
    completeForTownLoss: missing.length === 0 && lossReliefComplete,
    empireExtensions: Object.freeze({
      relief: Object.freeze({perTurn: empireRelief.perTurn, remaining: empireReliefRemaining}),
      cost: Object.freeze({perTurn: empireCost.perTurn, remaining: empireCostRemaining})
    }),
    evidence: Object.freeze({
      formula: "h(N')=town.happiness+P(N)-P(N'); relief=N-1 vs N, cost=N vs N+1",
      note: 'P is zero at/below cap and non-negative above cap; per-town values use each town current happiness'
    })
  });
  return Object.freeze({status: snapshot.status, snapshot});
}

export function createSettlementPointSnapshot(input) {
  const evaluated = evaluateSettlementPointCounts(input);
  return evaluated.snapshot === null
    ? Object.freeze({status: evaluated.status, snapshot: null, reason: evaluated.reason, missing: evaluated.missing || []})
    : evaluated.snapshot;
}

// Relief applies to surviving towns only. The removed town's per-town
// contribution is excluded from both per-turn and remaining totals. This is a
// filtered contribution view, NOT a new N-state snapshot.
export function reliefAfterTownLoss(snapshot, removedTownId) {
  if (!snapshot || !Array.isArray(snapshot.perTown)) return Object.freeze({status: 'invalid', reason: 'settlement-snapshot-required', relief: null});
  if (removedTownId === undefined) return Object.freeze({status: 'invalid', reason: 'removedTownId-required', relief: null});
  const survivors = snapshot.perTown.filter(town => String(town.id) !== String(removedTownId));
  const correction = snapshot.lossRelief?.byTown?.[String(removedTownId)];
  const missing = [...(snapshot.missing || [])];
  if (!correction) missing.push(`empire-relief-after-loss:${removedTownId}`);
  const perTurn = survivors.reduce((sum, town) => sum + town.perTurn.relief, 0) + (correction?.perTurn ?? 0);
  const remaining = survivors.reduce((sum, town) => sum + town.remaining.relief, 0) + (correction?.remaining ?? 0);
  const complete = snapshot.complete === true && correction !== undefined;
  return Object.freeze({
    status: complete ? 'estimated' : 'partial',
    perTurn,
    remaining,
    survivingTowns: survivors.map(town => town.id),
    removedTownId,
    atCap: snapshot.atCap,
    overCap: snapshot.overCap,
    complete,
    missing: Object.freeze([...new Set(missing)]),
    empireReliefGain: correction ? Object.freeze({perTurn: correction.perTurn, remaining: correction.remaining, source: correction.source, kind: correction.kind}) : null,
    evidence: Object.freeze({
      note: 'surviving-town relief plus the precomputed candidate-town empire relief gain only; removed town contribution excluded once; not a new-count snapshot'
    })
  });
}

export function costAfterTownGain(snapshot) {
  if (!snapshot || !snapshot.perTurn) return Object.freeze({status: 'invalid', reason: 'settlement-snapshot-required', cost: null});
  return Object.freeze({
    status: snapshot.complete ? 'estimated' : 'partial',
    perTurn: snapshot.perTurn.cost,
    remaining: snapshot.remaining.cost,
    atCap: snapshot.atCap,
    overCap: snapshot.overCap,
    complete: snapshot.complete,
    missing: snapshot.missing,
    evidence: Object.freeze({note: 'N->N+1 cost is zero unless N+1>cap; it can be positive at N==cap'})
  });
}
